<script setup lang="ts">import brands from '~/content/brands.json';import products from '~/content/products.json';import {whatsapp,track} from '~/utils/business';const {ar,c}=useCopy();const lp=useLocalePath();const route=useRoute();const b=brands.find(b=>b.slug===route.params.slug);if(!b)throw createError({statusCode:404,statusMessage:'Brand not found'});const brand=b!;usePageSeo(brand.name,brand.name);onMounted(()=>track('brand_view',{brand:brand.slug}));
</script><template><div><section class="section" :style="{background:brand.color}"><div class="container"><UiBreadcrumbs :title="brand.name"/><h1 class="sr-only">{{brand.name}}</h1><img :src="brand.logo" :alt="brand.name" width="420" height="180" style="max-width:400px;height:160px;object-fit:contain;margin-block:20px"/><p style="max-width:700px;font-size:20px">{{brand.story[ar?'ar':'en']}}</p><UiPill>{{brand.ageRange[ar?'ar':'en']}}</UiPill><div class="hero-ctas" style="margin-top:30px"><UiButton :href="whatsapp(c('أرغب بالاستفسار عن '+brand.name+' بالجملة','I would like to enquire about '+brand.name+' wholesale.'))">{{c('تواصل للجملة','Enquire wholesale')}} ↗</UiButton><UiButton variant="secondary" :to="lp('/visit')">{{c('زورونا','Visit us')}}</UiButton></div></div></section><section class="container section"><UiSectionHeader :title="c('من التشكيلة','From the collection')"/><div class="product-grid"><UiProductCard v-for="p in products.filter(x=>x.brand===brand.slug).slice(0,8)" :key="p.slug" :product="p"/></div></section></div></template>
